"""Explain disabled warnings and KMSAN Makefile basics in beginner Korean."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1881': ('특별 검사 기능을 빼도 일반 경고판까지 없어진다는 뜻은 아니에요. 같은 이름이 어떤 정의로 연결되는지 확인해요.', '검사 설정을 끈 경고 별명과 빈 함수의 역할을 구별합니다.', 'KMSAN 없음 쪽에서 KMSAN_WARN_ON→WARN_ON, enable·disable→빈 본문으로 연결하세요.', ['CONFIG_KMSAN은 커널을 만들 때 KMSAN 검사 기능을 넣을지 정하는 설정이에요. 넣은 빌드에서 잠시 kmsan_enabled를 끄는 것과, 처음부터 이 기능을 빼고 만드는 것은 다른 상황이에요.', '헤더의 #else 부분은 CONFIG_KMSAN이 없는 경우의 정의예요. 여기에는 #define KMSAN_WARN_ON WARN_ON이라고 적혀 있어요. 앞 이름을 일반 WARN_ON 이름으로 바꾸어 쓰는 별명이라는 뜻이에요.', '따라서 KMSAN을 빼도 이 이름이 아무 조건 계산도 없는 빈 매크로가 되는 것은 아니에요. 일반 WARN_ON의 규칙에 따라 조건을 검사하고 경고할 수 있어요. 일반 경고의 세부 동작은 해당 정의와 커널 설정에 따르므로 항상 출력된다고 단정하지 않아요.', 'KMSAN 활성 매크로에 있던 kmsan_enabled=false 쓰기와 panic_on_kmsan에 따른 BUG 분기는 이 별명 정의에 없어요. 일반 WARN_ON 자체가 설정에 따라 어떻게 처리하는지는 별도의 문제예요.', '같은 비활성 분기의 kmsan_enable_current와 kmsan_disable_current는 본문이 빈 inline 함수예요. 활성 구현처럼 현재 작업의 depth를 줄이거나 늘리지 않아요. 호출 형태를 유지하면서 KMSAN 상태 처리는 하지 않는 거예요.', '이름이 같다고 실행 코드도 같다고 생각하지 마세요. 사용하는 설정에서 선택된 정의가 별명인지, 빈 함수인지, 실제 구현인지 먼저 확인하면 어떤 효과가 남는지 구별할 수 있어요.'], [('KMSAN을 넣지 않은 분기의 KMSAN_WARN_ON은 무엇에 연결되나요?', ['아무 조건도 평가하지 않는 빈 코드예요', '일반 WARN_ON이에요'], '정답은 두 번째예요. #define의 오른쪽에 WARN_ON이 있어요. KMSAN 기능을 빼는 것과 모든 일반 경고를 없애는 것은 달라요.'), ('이 비활성 분기의 enable_current가 현재 작업 depth를 줄이나요?', ['아니요. 함수 본문이 비어 있어요', '네. 활성 구현과 똑같이 항상 줄여요'], '정답은 첫 번째예요. 같은 이름을 호출할 수 있어도 선택된 본문은 달라요. 실제 상태 변경이 있는지 중괄호 안을 확인하세요.')]), 'os1882': ('조립할 부품 목록과 완성된 기계가 움직이는 순서는 달라요. Makefile의 목록은 코드를 만드는 과정에서 쓸 부품을 정해요.', 'Makefile의 객체 파일 목록과 실행 순서·빌드 성공을 구별합니다.', 'core.c→core.o→다른 객체와 연결이라는 화살표를 그리고, obj-y의 여섯 이름을 옆에 적으세요.', ['Makefile은 C 언어 함수가 아니라 프로그램을 만드는 규칙과 변수를 적는 파일이에요. 소스를 컴파일하고 결과를 연결하는 과정을 빌드라고 불러요. 컴파일은 소스를 기계가 실행할 형태로 바꾸는 작업이에요.', 'obj-y := core.o instrumentation.o init.o hooks.o report.o shadow.o는 이 디렉터리에서 빌드에 넣을 객체 파일 여섯 개를 나열해요. .o는 C 소스 등을 컴파일해 만든 중간 결과 파일의 이름 끝부분이에요.', 'core는 핵심 검사, instrumentation은 컴파일러가 추가한 검사 코드와의 연결, init은 초기화, hooks는 다른 커널 동작과의 연결, report는 보고, shadow는 검사 정보 관리 구현을 담아요. 이름을 통해 앞서 읽은 C 파일과 연결할 수 있어요.', '이 목록 순서가 부팅 뒤 C 함수들이 반드시 실행되는 순서는 아니에요. 실행 순서는 함수 호출과 조건문 등을 따라 확인해야 해요. 여기서는 어떤 부품을 빌드에 포함하는지 읽어요.', '상위 mm/Makefile에는 obj-$(CONFIG_KMSAN) += kmsan/이 있어요. KMSAN 설정에 따라 이 디렉터리를 빌드에 포함하는 연결이에요. 안쪽 obj-y만 보고 모든 커널 설정에서 반드시 이 여섯 파일을 만든다고 결론내리지는 않아요.', '목록이 여섯 이름으로 펼쳐지는지 확인하는 것과 실제 컴파일·링크 성공은 달라요. 링크는 객체 파일들을 연결하는 작업이에요. 이름 목록을 읽거나 변수 결과를 확인한 것만으로 실제 커널을 만들고 실행했다는 뜻은 아니에요.'], [('obj-y에 적힌 .o 여섯 개는 무엇을 뜻하나요?', ['C 함수가 실행되는 정확한 순서예요', '이 디렉터리에서 빌드에 넣을 객체 파일 목록이에요'], '정답은 두 번째예요. Makefile은 빌드 규칙이에요. 목록의 첫 이름부터 함수가 실행된다고 읽으면 만드는 단계와 실행하는 단계를 혼동해요.'), ('목록이 여섯 이름으로 펼쳐지는지 확인하면 커널 링크 성공까지 증명되나요?', ['아니요. 목록 확인과 실제 컴파일·링크는 달라요', '네. 그 순간 모든 컴파일러와 링커 작업이 끝난 거예요'], '정답은 첫 번째예요. 빌드 대상 이름이 맞아도 실제 변환·연결 과정은 따로 실행해 확인해야 해요. 여기서 확인한 범위를 넘겨 해석하지 마세요.')]), 'os1883': ('검사원이 검사할 때마다 또 다른 검사원을 불러야 한다면 일이 반복될 수 있어요. 검사 도구 자신의 코드에는 별도의 빌드 규칙이 필요해요.', '검사 도구 자체의 계측 제외와 일반 코드 검사의 차이를 이해합니다.', 'runtime의 KMSAN·KCOV·UBSAN은 n, 별도 kmsan_test.o의 KMSAN은 y라고 나란히 적으세요.', ['instrumentation, 즉 계측은 프로그램 동작을 살피기 위해 코드를 덧붙이는 것이에요. KMSAN은 준비되지 않은 값 사용을, UBSAN은 C에서 허용되지 않는 여러 동작을 찾는 데 쓰여요. KCOV는 어느 코드가 실행됐는지 기록하는 기능이에요.', '이 Makefile은 KMSAN_SANITIZE, KCOV_INSTRUMENT, UBSAN_SANITIZE를 모두 n으로 정해요. n은 여기서 해당 계측을 넣지 않도록 지정하는 값이에요. 이 규칙은 검사 도구 자신의 runtime 코드를 만드는 문맥이에요.', '검사 도구 내부 동작에 다시 같은 검사나 기록 호출을 붙이면 내부 작업 도중 또 내부 작업을 시작하는 재진입이 생길 수 있어요. 추가 코드의 부수 효과도 고려해야 해요. 그래서 일반 검사 대상 코드와 도구 내부 코드를 같은 방식으로 만들지 않아요.', '이 세 값을 n으로 둔다고 Linux의 모든 코드에서 검사를 없앤다는 뜻은 아니에요. 이 디렉터리의 빌드 정책을 읽는 것이고, 다른 부분의 계측 여부는 그 설정과 규칙을 따로 봐요.', '아래에는 kmsan_test.o에 대해 KMSAN_SANITIZE_kmsan_test.o := y라는 개별 지정도 있어요. 이 파일은 조건에 따라 포함되는 테스트 코드예요. 테스트 대상에는 검사가 필요하므로 runtime의 기본값만 보고 이 파일도 반드시 n이라고 판단하면 안 돼요.', '별도의 사용자 프로그램 모형을 UBSan 등으로 검사하는 실습과 실제 커널 runtime의 UBSAN_SANITIZE 값은 다른 문맥이에요. 실습에 도구를 썼다는 사실이 원본 빌드 설정을 y로 바꾸지는 않아요.'], [('이 원본 runtime Makefile의 UBSAN_SANITIZE 값은 무엇인가요?', ['항상 y예요', 'n이에요'], '정답은 두 번째예요. 원문 변수에 n이 있어요. 별도 실습 모형을 검사 도구로 실행한 것과 이 빌드 설정은 구별하세요.'), ('검사 도구 자기 코드에 같은 계측을 피하는 이유는 무엇인가요?', ['재진입과 추가 검사 코드의 영향을 줄이려는 것이에요', '커널의 모든 일반 코드 검사까지 없애려는 것이에요'], '정답은 첫 번째예요. 도구 자신의 실행 경로를 위한 정책이에요. 이 디렉터리의 규칙을 커널 전체 검사 제거로 넓히면 안 돼요.')]), 'os1884': ('준비물 목록을 한 줄씩 덧붙이되 사용할 수 없는 준비물은 빼요. 빌드 옵션도 기본값과 지원 여부에 따라 목록을 만들어요.', 'Make 변수 대입·추가와 컴파일러 옵션 선택을 이해합니다.', '기본 옵션→지원되면 두 번째 옵션 추가→전처리 정의 추가라는 목록을 지원·미지원 두 경우로 적으세요.', ['CC_FLAGS_KMSAN_RUNTIME은 이 runtime을 컴파일할 때 전달할 옵션 목록이에요. 옵션은 컴파일러에게 어떤 방식으로 코드를 만들지 알려 주는 지시예요. 프로그램 실행 중 출력할 문장 목록이 아니에요.', '첫 줄의 :=는 오른쪽 값을 지금 펼쳐 변수에 정하는 방식이에요. 처음 목록은 -fno-stack-protector예요. 이는 스택 보호 계측을 넣지 않도록 하는 컴파일 옵션이에요. 여기서 스택은 함수 호출에 쓰는 저장 공간을 말해요.', '다음 +=는 기존 목록을 버리지 않고 뒤에 값을 더해요. $(call cc-option,-fno-conserve-stack)은 Linux 빌드 도우미 cc-option을 통해 그 옵션을 사용할 수 있는지 확인해 결과를 받아요.', '지원되면 -fno-conserve-stack이 더해지고 지원되지 않으면 이 호출에서는 대체값을 주지 않았으므로 추가할 옵션이 없어요. 옵션 이름은 스택 사용량을 줄이려는 컴파일러 동작을 끄는 지시예요. 무조건 모든 컴파일러에 강제로 전달하는 것은 아니에요.', '마지막에는 -DDISABLE_BRANCH_PROFILING을 더해요. -D는 C 전처리 이름을 정의하는 옵션이에요. DISABLE_BRANCH_PROFILING이라는 이름을 정의해 분기 실행 기록을 막는 코드 선택에 사용해요. runtime마다 이 문자열을 화면에 찍는 동작은 아니에요.', '지원 여부를 미리 정해 두는 작은 모형은 목록 조합만 확인해요. 실제 cc-option은 빌드에 사용할 컴파일러를 통해 옵션을 시험하는 도우미예요. 모형의 지원 0·1을 실제 설치된 컴파일러의 지원 판정으로 오해하지 마세요.'], [('cc-option이 -fno-conserve-stack을 지원하지 않는 경우 이 옵션이 목록에 들어가나요?', ['네. 모든 경우에 강제로 넣어요', '아니요. 이 옵션은 생략돼요'], '정답은 두 번째예요. 도우미가 반환한 값을 +=로 더해요. 미지원일 때 대체 옵션도 지정하지 않았으므로 이 항목만 빠지고 다른 목록은 남아요.'), ('-DDISABLE_BRANCH_PROFILING은 어디에 쓰는 지시인가요?', ['C 컴파일 과정의 전처리 정의로 전달해요', '프로그램 실행 때마다 같은 문자열을 출력해요'], '정답은 첫 번째예요. -D는 이름을 정의하는 컴파일 옵션이에요. Makefile에서 옵션을 모으는 일과 실행 중 문장을 출력하는 일을 구별하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_466.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
